3

Cluster Members:
[
  {
    "name": "TESTS_ASSUMPTION_WITH_PROBE",
    "definition": "A targeted action tests a specific uncertainty or hypothesis identified in reasoning, and the resulting observation provides interpretable evidence bearing on that uncertainty.",
    "parameters": [
      {
        "name": "probe_action",
        "type": "action",
        "description": "The targeted action that probes the uncertainty or hypothesis."
      },
      {
        "name": "assumption_reasoning",
        "type": "reasoning",
        "description": "The reasoning node identifying the hypothesis, property, or uncertainty being tested."
      },
      {
        "name": "probe_result",
        "type": "observation",
        "description": "The observation reporting a result relevant to the hypothesis or uncertainty."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific uncertainty, hypothesis, or property to be checked.",
      "The probe action is directed at obtaining evidence about that specific uncertainty.",
      "The observation reports a result that can be interpreted as evidence about the uncertainty."
    ],
    "exclusion_conditions": [
      "The action is unrelated to the stated uncertainty or hypothesis.",
      "The observation does not address the uncertainty being tested.",
      "No identifiable uncertainty or hypothesis motivates the action.",
      "The uncertainty or hypothesis is formulated only after the result is observed, so the action did not serve as a test of it."
    ]
  },
  {
    "name": "CONDUCTS_RESIDUAL_RISK_SWEEP",
    "definition": "Motivated by concern about overlooked instances after targeted work has been completed, the reasoning calls for a broad search beyond the already identified targets; the action scans a wider set of locations, patterns, or artifact classes; and the resulting observation is interpreted to rule out additional actionable instances or to identify them.",
    "parameters": [
      {
        "name": "sweep_reasoning",
        "type": "reasoning",
        "description": "The reasoning that motivates a broad search for overlooked instances and/or draws a conclusion from the sweep result."
      },
      {
        "name": "sweep_action",
        "type": "action",
        "description": "The action scanning locations, patterns, or artifact classes beyond the already identified targets."
      },
      {
        "name": "sweep_observation",
        "type": "observation",
        "description": "The observation reporting whether additional actionable instances were found."
      }
    ],
    "assertion_conditions": [
      "The reasoning motivates a broad search for overlooked instances after targeted remediation or verification work.",
      "The action searches across a wider set of locations, patterns, or artifact classes than the already known targets.",
      "The observation is examined for additional actionable instances and either reveals none or identifies new ones."
    ],
    "exclusion_conditions": [
      "The action only rechecks the already known target values or locations.",
      "No broader residual-risk search is motivated.",
      "The observation is not interpreted for overlooked instances.",
      "The scan is the initial discovery search rather than a post-work check for residual cases."
    ]
  }
]

